def replay_replacements(replacements: list[Replacement], dry_run: bool = False) -> dict[str, int]:
    """Re-apply replacements to their target files. Returns counts of applied per file.

    Uses virtual file state tracking to correctly handle chained edits even in dry-run mode.
    """
    counts: dict[str, int] = {}
    # Track virtual file contents to handle edit chains
    virtual_contents: dict[str, str] = {}

    for r in replacements:
        if not os.path.exists(r.file_path):
            print(f"  SKIP (file not found): {r.file_path}", file=sys.stderr)
            continue

        if r.file_path not in virtual_contents:
            with open(r.file_path, "r", encoding="utf-8") as f:
                virtual_contents[r.file_path] = f.read()

        content = virtual_contents[r.file_path]

        if r.new_string in content:
            # Already applied
            continue

        if r.old_string not in content:
            print(
                f"  SKIP (oldString not found): {r.timestamp} "
                f"{os.path.basename(r.file_path)} "
                f"old={len(r.old_string)} new={len(r.new_string)}",
                file=sys.stderr,
            )
            continue

        new_content = content.replace(r.old_string, r.new_string, 1)
        virtual_contents[r.file_path] = new_content

        if dry_run:
            print(f"  WOULD APPLY: {r.timestamp} {os.path.basename(r.file_path)}")
        else:
            print(f"  APPLIED: {r.timestamp} {os.path.basename(r.file_path)}")

        counts[r.file_path] = counts.get(r.file_path, 0) + 1

    # Write all modified files at the end
    if not dry_run:
        for fp, content in virtual_contents.items():
            with open(fp, "r", encoding="utf-8") as f:
                original = f.read()
            if content != original:
                with open(fp, "w", encoding="utf-8") as f:
                    f.write(content)

    return counts

